INSERT INTO Language_en_US(Tag,Text) VALUES
 ('TXT_KEY_PALEO_CIV','The Paleontological Directorate'),
 ('TXT_KEY_PALEO_SHORT','Paleontological Directorate'),
 ('TXT_KEY_PALEO_ADJECTIVE','Directorate'),
 ('TXT_KEY_PALEO_LEADER','Director Emeritus Othmar'),
 ('TXT_KEY_PALEO_TRAIT','The Earth Remembers'),
 ('TXT_KEY_PALEO_TRAIT_HELP','Each city with a Library-class building gains +1 [ICON_RESEARCH] Science. Independently, each city with a University-class building gains +1 [ICON_CULTURE] Culture. Real or free buildings and unique replacements qualify; each class grants its bonus once per city.'),
 ('TXT_KEY_PALEO_CIV_PEDIA','The Paleontological Directorate is an eccentric scientific republic devoted to the ancient earth. Its scholars unearth fossils and preserve antiquities, gathering evidence of lost ecosystems in grand museums. Patience and curiosity guide its universities, while field expeditions carry discovery beyond its borders.'),
 ('TXT_KEY_PALEO_STRATEGY','Build Libraries and Universities throughout your republic, then Natural History Museums. Pursue Science and Culture while sending Fossil Expeditions to Antiquity and Hidden Antiquity Sites. Secure access through diplomacy and preserve the collections.'),
 ('TXT_KEY_PALEO_LEADER_PEDIA','Director Emeritus Othmar, Keeper of the Ancient Earth, is a stout elderly fossil scholar with an enormous magnifying monocle, wild white side-whiskers, an ivory laboratory coat and a vermilion waistcoat. He cradles prized ammonites as though they were beloved pets. He welcomes visitors to a gigantic museum whose most imposing dinosaur skeleton is not quite correctly assembled. Generally peaceful, he is fiercely protective of scientific access and the collections.'),
 ('TXT_KEY_PALEO_UNIT','Fossil Expedition'),
 ('TXT_KEY_PALEO_UNIT_HELP','Replaces the Archaeologist. Retains all active Archaeologist rules and excavations, with +1 Movement and +1 Sight. Field Discovery: successfully completing an excavation grants 17/25/38/75 [ICON_RESEARCH] Science on Quick/Standard/Epic/Marathon, once per site, before the normal archaeology choice. Artifact and Landmark choices both qualify.'),
 ('TXT_KEY_PALEO_UNIT_PEDIA','Equipped with geological tools, brushes and specimen crates, Fossil Expeditions investigate the remains of the ancient world. Their work follows ordinary archaeological practice, preserving every normal Artifact and Landmark outcome while sharing field discoveries with the republic.'),
 ('TXT_KEY_PALEO_UNIT_STRATEGY','Use the extra Movement and Sight to reach and survey sites. The unit that completes the dig must be a Directorate Fossil Expedition; starting or cancelling a dig grants nothing. Science completes current research with native overflow; with no selected research it is banked as overflow until research resumes.'),
 ('TXT_KEY_PALEO_MUSEUM','Natural History Museum'),
 ('TXT_KEY_PALEO_MUSEUM_HELP','Replaces the Museum. Retains all active Museum effects, costs, prerequisites, Great Work slots and theming bonuses. Adds permanent +2 [ICON_RESEARCH] Science and +1 [ICON_CULTURE] Culture, with no Great Work or theming requirement.'),
 ('TXT_KEY_PALEO_MUSEUM_PEDIA','Grand halls display ammonites, petrified forests and reconstructed skeletons. Natural History Museums connect the study of antiquity with the far older history of life, bringing scientific inquiry and public learning together beneath one roof.'),
 ('TXT_KEY_PALEO_MUSEUM_STRATEGY','Build these museums for unconditional Science and Culture. Artifacts and Great Works retain their normal Museum benefits; the unique yields apply even when the slots are empty.'),
 ('TXT_KEY_PALEO_PROMOTION','Field Observation'),
 ('TXT_KEY_PALEO_PROMOTION_HELP','+1 Sight. No combat or protection bonus.'),
 ('TXT_KEY_PALEO_DUMMY','The Earth Remembers'),
 ('TXT_KEY_PALEO_DUMMY_HELP','Internal city-yield controller. Cannot be constructed or purchased.'),
 ('TXT_KEY_PALEO_GREETING_1','Ah! A visitor! Wonderful! Tell me, have you ever seen a fossilized ammonite? No? THEN YOU MUST COME INSIDE!'),
 ('TXT_KEY_PALEO_WAR_1','You have repeatedly obstructed our scientific expeditions. I regret to inform you that the Directorate has authorized... more aggressive fieldwork.'),
 ('TXT_KEY_PALEO_ATTACKED_1','War?! But we''ve only just discovered an entirely new species! Can''t this wait?'),
 ('TXT_KEY_PALEO_DEFEAT_1','Take our cities... but please... preserve the collections...'),
 ('TXT_KEY_PALEO_PEACE_1','Wonderful. Now, where did I leave my field notes?'),
 ('TXT_KEY_PALEO_FRIENDLY_1','Come inside! The collections have grown since your last visit!'),
 ('TXT_KEY_PALEO_NEUTRAL_1','Welcome. Please mind the specimen crates.'),
 ('TXT_KEY_PALEO_HOSTILE_1','Our expeditions require access. I trust you understand.'),
 ('TXT_KEY_PALEO_TRADE_1','An excellent exchange. Knowledge thrives through cooperation.'),
 ('TXT_KEY_PALEO_FALLBACK_1','The Directorate will consider your proposal with scholarly care.'),
 ('TXT_KEY_PALEO_DAWN','Esteemed Director Emeritus Othmar, Keeper of the Ancient Earth, your people await your discoveries.[NEWLINE][NEWLINE]Long before the first cities were founded, before the first kingdoms rose, before humanity learned to shape the world around it, the earth was already ancient.[NEWLINE][NEWLINE]Countless creatures walked beneath forgotten skies. Great forests covered lands that would one day become deserts. Entire worlds flourished and disappeared, leaving only their remains buried beneath the soil.[NEWLINE][NEWLINE]Yet your people have dedicated themselves to uncovering these forgotten histories.[NEWLINE][NEWLINE]Through patience, curiosity, and tireless exploration, the scholars of the Directorate have begun revealing the secrets of the ancient earth.[NEWLINE][NEWLINE]Now, a new age of discovery awaits.[NEWLINE][NEWLINE]Build your cities. Establish your universities. Send your expeditions into the unknown.[NEWLINE][NEWLINE]Will your civilization uncover the greatest mysteries of the past?[NEWLINE][NEWLINE]And through understanding yesterday, will you shape the future of the world?'),
 ('TXT_KEY_PALEO_CITY_1','Stratum Prime'),
 ('TXT_KEY_PALEO_CITY_2','Ammonite Bay'),
 ('TXT_KEY_PALEO_CITY_3','Deep Time'),
